sw $t3, 12($t6)
add $t6, $t6, $t5

sw $t3, 0($t6)
sw $t3, 4($t6)
sw $t3, 8($t6)
sw $t3, 12($t6)
add $t6, $t6, $t5

jal BUFFTOSCREEN

EXIT:
    li $v0, 10 # terminate the program gracefully
    syscall

DRAWCHARACTER:
    lw $t0, displayBuffer # $t0 stores the base address for display

    # from DB32 colour pallet, 4 colours used
    li $t1, 0x3f3f74 # $t1 stores the blue
    li $t2, 0x5b6ee1 # $t2 stores the light blue
    li $t3, 0x323c39 # $t3 stores the grey
    li $t4, 0xd95763 # $t4 stores the red

    lw $t5, displayWidth
    sll $t5, $t5, 2
    lw $t6, characterX
    sll $t6, $t6, 2		# turns x into byte offset (mult by 4)
    lw $t7, characterY

    mul $t7, $t5, $t7	
    add $t6, $t6, $t7
    add $t6, $t6, $t0
    #t5 is displaywidth
    #t6 is x + displaywidth*y
    #t6 is used as the address on the display that corrispods to the row with character x value

    sw $t1, 20($t6)
    sw $t1, 24($t6)
    sw $t1, 28($t6)

    add $t6, $t6, $t5

    sw $t3, 12($t6)

    sw $t1, 24($t6)
    sw $t1, 28($t6)
    sw $t1, 32($t6)

    sw $t2, 36($t6)
    sw $t2, 40($t6)
    sw $t2, 44($t6)

    add $t6, $t6, $t5

    sw $t4, 0($t6)
    sw $t4, 4($t6)

    sw $t3, 16($t6)
    sw $t3, 20($t6)

    sw $t1, 24($t6)
    sw $t1, 28($t6)
    sw $t1, 32($t6)
    sw $t1, 36($t6)
    sw $t1, 40($t6)

    sw $t2, 44($t6)
    sw $t2, 48($t6)
    sw $t2, 52($t6)

    add $t6, $t6, $t5

    sw $t4, 4($t6)
    sw $t4, 8($t6)
    sw $t4, 12($t6)

    sw $t3, 16($t6)
    sw $t3, 20($t6)

    sw $t1, 24($t6)
    sw $t1, 28($t6)
    sw $t1, 32($t6)
    sw $t1, 36($t6)
    sw $t1, 40($t6)
    sw $t1, 44($t6)
    sw $t1, 48($t6)

    sw $t2, 52($t6)
    sw $t2, 56($t6)

    add $t6, $t6, $t5

    sw $t4, 8($t6)
    sw $t4, 12($t6)

    sw $t3, 16($t6)
    sw $t3, 20($t6)

    sw $t1, 24($t6)
    sw $t1, 28($t6)
    sw $t1, 32($t6)
    sw $t1, 36($t6)
    sw $t1, 40($t6)
    sw $t1, 44($t6)
    sw $t1, 48($t6)
    sw $t1, 52($t6)
    sw $t1, 56($t6)

    sw $t3, 60($t6)

    add $t6, $t6, $t5

    sw $t4, 0($t6)
    sw $t4, 8($t6)

    sw $t3, 16($t6)
    sw $t3, 20($t6)

    sw $t1, 24($t6)
    sw $t1, 28($t6)
    sw $t1, 32($t6)
    sw $t1, 36($t6)
    sw $t1, 40($t6)
    sw $t1, 44($t6)
    sw $t1, 48($t6)

    sw $t3, 52($t6)
    sw $t3, 56($t6)
    sw $t3, 60($t6)

    add $t6, $t6, $t5

    sw $t4, 4($t6)

    sw $t3, 12($t6)

    sw $t1, 24($t6)
    sw $t1, 28($t6)
    sw $t1, 32($t6)
    sw $t1, 36($t6)

    sw $t3, 40($t6)
    sw $t3, 44($t6)
    sw $t3, 48($t6)
    sw $t3, 52($t6)

    add $t6, $t6, $t5

    sw $t3, 20($t6)
    sw $t3, 24($t6)
    sw $t3, 28($t6)
    sw $t3, 32($t6)
    sw $t3, 36($t6)

    jr $ra

CLEARSCREEN:
    lw $t0, displayBuffer
    lw $t1, displayWidth
    sll $t1, $t1, 2
    lw $t2, displayHeight

    mul $t3, $t1, $t2
    add $t3, $t3, $t0

    li $t4, 0
    CLEARSCREENLOOP:
    beq $t0, $t3, CLEARSCREENENDLOOP
    sw $t4, ($t0)
    addi $t0, $t0, 4
    j CLEARSCREENLOOP
    CLEARSCREENENDLOOP:

    jr $ra

BUFFTOSCREEN:
    lw $t0, displayBuffer
    lw $t1, displayWidth
    sll $t1, $t1, 2
    lw $t2, displayHeight

    mul $t3, $t1, $t2
    add $t3, $t3, $t0

    lw $t4, displayAddress

    BUFFTOSCREENLOOP:
    beq $t0, $t3, BUFFTOSCREENENDLOOP
    lw $t9, ($t0)
    sw $t9, ($t4)
    addi $t0, $t0, 4
    addi $t4, $t4, 4
    j BUFFTOSCREENLOOP
    BUFFTOSCREENENDLOOP:

    jr $ra

DRAWGAMEBACKGROUND:
    la $t0, backgroundImage
    lw $t1, displayWidth
    sll $t1, $t1, 2
    lw $t2, displayHeight

    mul $t3, $t1, $t2
    add $t3, $t3, $t0

    lw $t4, displayBuffer

    DRAWGAMEBACKGROUNDLOOP:
    beq $t0, $t3, DRAWGAMEBACKGROUNDENDLOOP
    lw $t9, ($t0)
    sw $t9, ($t4)
    addi $t0, $t0, 4
    addi $t4, $t4, 4
    j DRAWGAMEBACKGROUNDLOOP
    DRAWGAMEBACKGROUNDENDLOOP:

    jr $ra

KEYBOARDINPUT:
    li $t9, 0xffff0000
    lw $t8, 0($t9)
    bne $t8, 1, KEYBOARDINPUTDONE
    lw $t2, 4($t9) # this assumes $t9 is set to 0xfff0000from before

    bne $t2, 0x77, KEYBOARDINPUTW # ASCII code of 'w' is 0x77 or 119 in decimal
    lw $t0, characterY
    addi $t0, $t0, -2
    sw $t0, characterY
    KEYBOARDINPUTW:

    bne $t2, 0x61, KEYBOARDINPUTA # ASCII code of 'a' is 0x61 or 97 in decimal
    lw $t0, characterX
    addi $t0, $t0, -2
    sw $t0, characterX
    KEYBOARDINPUTA:
    
    bne $t2, 0x73, KEYBOARDINPUTS # ASCII code of 's' is 0x73 or 115 in decimal
    lw $t0, characterY
    addi $t0, $t0, 2
    sw $t0, characterY
    KEYBOARDINPUTS:

    bne $t2, 0x64, KEYBOARDINPUTD # ASCII code of 'd' is 0x61 or 100 in decimal
    lw $t0, characterX
    addi $t0, $t0, 2
    sw $t0, characterX
    KEYBOARDINPUTD:

    KEYBOARDINPUTDONE:
    jr $ra

CHARACTERMOVEMENT:

    jr $ra
